sub_block('function eKit(v){','return elevFrame(W,H,s,\'Развёртка кухни\');\n}',r'''function eKit(v){
  const W=2346+5223,H=2700,y=h=>H-h, ub=x=>2346-x, ul=yy=>2346+(8973-yy);
  const low=v==='green'?'#2F4235':'url(#oak)', tap=v==='green'?'#151515':'url(#brass)';
  let s=R(0,0,W,H,'fill="#F2F0EB" class="hair"');
  [[7944,6877],[5388,4288]].forEach(([a,b])=>s+=R(ul(a),y(2400),a-b,1400,'class="glass"')+`<line x1="${ul(a)+(a-b)/2}" y1="${y(2400)}" x2="${ul(a)+(a-b)/2}" y2="${y(1000)}" class="hair"/>`);
  s+=R(ub(1800),y(1500),1800,600,'fill="url(#mw)" class="hair"');
  s+=R(2346,y(1500),ul(7944)-2346,600,'fill="url(#mw)" class="hair"');
  const run=(a,b)=>R(a,y(870),b-a,770,`fill="${low}" class="hair"`)+R(a,y(100),b-a,100,'fill="#111"')+R(a,y(900),b-a,30,'fill="url(#mw)" stroke="#999" stroke-width="6"');
  s+=run(ub(1800),2346)+run(2346,ul(6877));
  for(let x=ub(1800)+600;x<2346;x+=600) s+=`<line x1="${x}" y1="${y(870)}" x2="${x}" y2="${y(100)}" stroke="#00000033" stroke-width="8"/>`;
  for(let x=2346+600;x<ul(6877);x+=600) s+=`<line x1="${x}" y1="${y(870)}" x2="${x}" y2="${y(100)}" stroke="#00000033" stroke-width="8"/>`;
  s+=R(ub(1500),y(800),600,580,'fill="#151515"')+R(ub(1500),y(915),600,15,'fill="#111"');
  s+=R(0,0,2346,y(1500),'fill="#F7F6F3" class="hair"');
  for(let x=586;x<2346;x+=586) s+=`<line x1="${x}" y1="0" x2="${x}" y2="${y(1500)}" class="hair"/>`;
  const sx=ul(7410); s+=R(sx-250,y(900),500,30,'fill="#2a2a2a"')+R(sx-14,y(1240),28,340,`fill="${tap}"`)+R(sx-14,y(1240),160,28,`fill="${tap}"`);
  s+=`<line x1="2346" y1="0" x2="2346" y2="${H}" stroke="var(--d-ink)" stroke-width="10" stroke-dasharray="40 30"/>`;
  s+=T(1173,-90,'верхние шкафы на всю стену','tiny')+T(ul(7410),-90,'мойка у окна','tiny')+T(ul(6877)+150,y(450),'дальше без гарнитура','tiny','style="fill:#777;text-anchor:start"');
  s+=T(1173,H+260,'стена слева от входа','tiny')+T(2346+2611,H+260,'левая стена (окна)','tiny');
  s+=dimV(0,H,-150,'2700')+dimV(y(900),H,W+150,'900')+dimV(y(1500),H,W+380,'1500');
  return elevFrame(W,H,s,'Развёртка кухни');
}''')
